using EEMS.Modules.Reporting.Domain;using Microsoft.EntityFrameworkCore;namespace EEMS.Modules.Reporting.Infrastructure;
public sealed class ReportingDbContext(DbContextOptions<ReportingDbContext> o):DbContext(o){public DbSet<AuditLog> AuditLogs=>Set<AuditLog>();public DbSet<SecurityEvent> SecurityEvents=>Set<SecurityEvent>();public DbSet<ExportState> ExportStates=>Set<ExportState>();public DbSet<ExportLog> ExportLogs=>Set<ExportLog>();public DbSet<OutboxMessage> Outbox=>Set<OutboxMessage>();
#pragma warning disable CA1725
protected override void OnModelCreating(ModelBuilder b){b.HasDefaultSchema("audit");var a=b.Entity<AuditLog>();a.ToTable("audit_logs");a.HasKey(x=>x.Id);a.Property(x=>x.Id).HasColumnName("audit_log_id").ValueGeneratedOnAdd();a.Property(x=>x.TenantId).HasColumnName("tenant_id");a.Property(x=>x.ActorUserId).HasColumnName("actor_user_id");a.Property(x=>x.Action).HasColumnName("action").HasMaxLength(100);a.Property(x=>x.EntityType).HasColumnName("entity_type").HasMaxLength(120);a.Property(x=>x.EntityId).HasColumnName("entity_id").HasMaxLength(120);a.Property(x=>x.CorrelationId).HasColumnName("correlation_id").HasMaxLength(100);a.Property(x=>x.MetadataJson).HasColumnName("metadata_json").HasColumnType("jsonb");a.Property(x=>x.OccurredAtUtc).HasColumnName("occurred_at");a.HasIndex(x=>new{x.TenantId,x.OccurredAtUtc});
var s=b.Entity<SecurityEvent>();s.ToTable("security_events");s.HasKey(x=>x.Id);s.Property(x=>x.Id).HasColumnName("security_event_id");s.Property(x=>x.TenantId).HasColumnName("tenant_id");s.Property(x=>x.UserId).HasColumnName("user_id");s.Property(x=>x.EventType).HasColumnName("event_type").HasMaxLength(100);s.Property(x=>x.Source).HasColumnName("source").HasMaxLength(160);s.Property(x=>x.Detail).HasColumnName("detail").HasMaxLength(4000);s.Property(x=>x.CorrelationId).HasColumnName("correlation_id").HasMaxLength(100);s.Property(x=>x.OccurredAtUtc).HasColumnName("occurred_at");
var st=b.Entity<ExportState>();st.ToTable("export_states");st.HasKey(x=>x.Id);st.Property(x=>x.Id).HasColumnName("export_state_id").ValueGeneratedNever();st.Property(x=>x.Code).HasColumnName("code").HasMaxLength(40);st.Property(x=>x.Name).HasColumnName("name").HasMaxLength(100);st.Property(x=>x.IsTerminal).HasColumnName("is_terminal");st.Property(x=>x.IsActive).HasColumnName("is_active");st.HasIndex(x=>x.Code).IsUnique();
var e=b.Entity<ExportLog>();e.ToTable("export_logs");e.HasKey(x=>x.Id);e.Property(x=>x.Id).HasColumnName("export_log_id");e.Property(x=>x.TenantId).HasColumnName("tenant_id");e.Property(x=>x.RequestedByUserId).HasColumnName("requested_by_user_id");e.Property(x=>x.StateId).HasColumnName("export_state_id");e.Property(x=>x.ReportType).HasColumnName("report_type").HasMaxLength(100);e.Property(x=>x.Format).HasColumnName("format").HasMaxLength(20);e.Property(x=>x.FiltersJson).HasColumnName("filters_json").HasColumnType("jsonb");e.Property(x=>x.CorrelationId).HasColumnName("correlation_id").HasMaxLength(100);e.Property(x=>x.StorageKey).HasColumnName("storage_key").HasMaxLength(500);e.Property(x=>x.RequestedAtUtc).HasColumnName("requested_at");e.Property(x=>x.CompletedAtUtc).HasColumnName("completed_at");e.HasOne<ExportState>().WithMany().HasForeignKey(x=>x.StateId).OnDelete(DeleteBehavior.Restrict);
var o=b.Entity<OutboxMessage>();o.ToTable("outbox_messages");o.HasKey(x=>x.Id);o.Property(x=>x.Id).HasColumnName("outbox_message_id");o.Property(x=>x.TenantId).HasColumnName("tenant_id");o.Property(x=>x.MessageType).HasColumnName("message_type").HasMaxLength(160);o.Property(x=>x.PayloadJson).HasColumnName("payload_json").HasColumnType("jsonb");o.Property(x=>x.CorrelationId).HasColumnName("correlation_id").HasMaxLength(100);o.Property(x=>x.OccurredAtUtc).HasColumnName("occurred_at");o.Property(x=>x.ProcessedAtUtc).HasColumnName("processed_at");}}
